import itertools, random, sympy as sp
def sort_sign(seq):
    seq=list(seq)
    if len(set(seq))<len(seq): return 0
    s=1
    for i in range(len(seq)):
        for j in range(len(seq)-1-i):
            if seq[j]>seq[j+1]:
                seq[j],seq[j+1]=seq[j+1],seq[j]; s=-s
    return s
random.seed(7)
n=4
for _ in range(20):
    A=[[random.randint(-4,4) for _ in range(n)] for _ in range(n)]
    tot=0
    for idx in itertools.product(range(n),repeat=n):
        sg=sort_sign(idx)
        if sg:
            p=1
            for j in range(n): p*=A[idx[j]][j]
            tot+=sg*p
    assert tot==sp.Matrix(A).det()

