    for b in parts(2):
        L=max(len(a),len(b)); a2=a+[0]*(L-len(a)); b2=b+[0]*(L-len(b))
        inv=sorted(2**x*3**y for x,y in zip(a2,b2))
        res.add(tuple(inv))
